public sealed class TokenOptions
{
    public required string Issuer { get; init; }
    public required string Audience { get; init; }
    public string? TenantClaim { get; init; }
}

public static bool TryReadBearer(
    string? header,
    [NotNullWhen(true)] out string? token)
{
    token = null;
    if (header is not { Length: > 7 } || !header.StartsWith("Bearer ", StringComparison.Ordinal))
        return false;
    token = header["Bearer ".Length..];
    return token.Length > 0;
}

public bool TryGet<T>(string key, [MaybeNullWhen(false)] out T value)
{
    if (!_store.TryGetValue(key, out object? raw))
    {
        value = default!;
        return false;
    }
    value = (T)raw;
    return true;
}

[return: MaybeNull]
public T Find<T>(string id)
{
    return _items.TryGetValue(id, out var item) ? item : default!;
